"""Code metrics for ``opi/``, measured against docs/development/coding-rules.md.

Reports per module, per function and per class how far the code is from the thresholds in
chapters 3 and 4, plus the import arrows between the layer packages of chapter 5. The
cleanup rounds use it to show the difference they made, so the counting rules must stay
stable: they are the yardstick, not the code they measure.
"""

from __future__ import annotations

import argparse
import ast
import csv
import sys
from dataclasses import dataclass
from pathlib import Path

#: ``opi/migrations`` is generated by alembic and is not written against these rules.
EXCLUDED_DIRS = frozenset({"migrations"})

# Chapter 3: functions.
FUNCTION_LINES_GUIDE = 20
FUNCTION_LINES_SIGNAL = 40
FUNCTION_LINES_SPLIT = 60
PARAMETERS_MAX = 4
DEPTH_MAX = 3
COMPLEXITY_MAX = 10

# Chapter 4: classes and modules.
MODULE_LINES_GUIDE = 300
MODULE_LINES_SIGNAL = 500
MODULE_LINES_SPLIT = 800
CLASS_LINES_GUIDE = 200
CLASS_LINES_SPLIT = 500

#: The three ways a module can reach another one. Only ``top_level`` runs on import, and
#: only ``top_level`` is a dependency a layer gate can enforce.
IMPORT_KINDS = ("top_level", "in_function", "type_checking")


@dataclass(frozen=True)
class FunctionMetrics:
    """One function or method. A nested function is an entry of its own."""

    module: str
    qualname: str
    line: int
    lines: int
    complexity: int
    parameters: int
    depth: int


@dataclass(frozen=True)
class ClassMetrics:
    module: str
    name: str
    line: int
    lines: int
    methods: int


@dataclass(frozen=True)
class ModuleMetrics:
    module: str
    path: str
    lines: int
    classes: int
    functions: int


@dataclass(frozen=True)
class ImportMetrics:
    """One import statement, with the dotted name it reaches."""

    module: str
    target: str
    kind: str
    line: int


@dataclass
class Report:
    modules: list[ModuleMetrics]
    functions: list[FunctionMetrics]
    classes: list[ClassMetrics]
    imports: list[ImportMetrics]


def module_name(path: Path, root: Path) -> str:
    """Dotted name of a file, with ``__init__`` standing for its package."""
    parts = [root.name, *path.relative_to(root).with_suffix("").parts]
    if parts[-1] == "__init__":
        parts.pop()
    return ".".join(parts)


def package_of(module: str, root_package: str) -> str:
    """The layer package a module belongs to: the first level under ``opi``.

    Chapter 5 draws its layers at that level, so that is where an arrow is interesting:
    ``opi.forms.visualizers.providers`` lives in ``opi.forms``; a module straight under
    ``opi``, such as ``opi.server``, is a level of its own.
    """
    parts = module.split(".")
    if parts[0] != root_package:
        return parts[0]
    return ".".join(parts[:2]) if len(parts) > 1 else root_package


def source_files(root: Path) -> list[Path]:
    """Every Python file under ``root``, without the excluded packages."""
    return sorted(
        path
        for path in root.rglob("*.py")
        if not EXCLUDED_DIRS & set(path.relative_to(root).parts[:-1]) and "__pycache__" not in path.parts
    )


def _parameter_count(node: ast.FunctionDef | ast.AsyncFunctionDef, is_method: bool) -> int:
    """Declared parameters, without the bound ``self``/``cls`` of a method."""
    args = node.args
    total = len(args.posonlyargs) + len(args.args) + len(args.kwonlyargs)
    total += bool(args.vararg) + bool(args.kwarg)
    first = (args.posonlyargs or args.args or [None])[0]
    if is_method and first is not None and first.arg in ("self", "cls"):
        total -= 1
    return total


#: Statements that open a new nesting level and that each add one path.
_BRANCH_STATEMENTS = (ast.If, ast.For, ast.AsyncFor, ast.While)
#: Statements that open a new nesting level without being a decision on their own.
_BLOCK_STATEMENTS = (*_BRANCH_STATEMENTS, ast.With, ast.AsyncWith, ast.Try, ast.Match)
_NESTED_SCOPES = (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)


def _own_body(node: ast.AST) -> list[ast.AST]:
    """The nodes of a function body, without the bodies of functions nested in it."""
    own: list[ast.AST] = []
    for child in ast.iter_child_nodes(node):
        if isinstance(child, _NESTED_SCOPES):
            continue
        own.append(child)
        own.extend(_own_body(child))
    return own


def complexity_of(node: ast.FunctionDef | ast.AsyncFunctionDef) -> int:
    """Cyclomatic complexity: one path, plus one per decision in this function's own body.

    A nested function keeps its own decisions, so a function does not inherit the
    complexity of the helper it declares.
    """
    total = 1
    for child in _own_body(node):
        if isinstance(child, (*_BRANCH_STATEMENTS, ast.ExceptHandler, ast.IfExp, ast.Assert, ast.match_case)):
            total += 1
        elif isinstance(child, ast.BoolOp):
            total += len(child.values) - 1
        elif isinstance(child, ast.comprehension):
            total += 1 + len(child.ifs)
    return total


def depth_of(node: ast.FunctionDef | ast.AsyncFunctionDef) -> int:
    """Deepest nesting of block statements in this function's own body.

    An ``elif`` chain stays on one level: the parser stores it as an ``If`` inside the
    ``orelse`` of the one before, which would otherwise read a flat chain as deep nesting.
    """

    def walk(body: list[ast.stmt], level: int) -> int:
        deepest = level
        for statement in body:
            if isinstance(statement, _NESTED_SCOPES):
                continue
            if isinstance(statement, _BLOCK_STATEMENTS):
                deepest = max(deepest, _walk_block(statement, level))
            else:
                deepest = max(deepest, walk(getattr(statement, "body", []) or [], level))
        return deepest

    def _walk_block(statement: ast.stmt, level: int) -> int:
        orelse = getattr(statement, "orelse", []) or []
        elif_chain = isinstance(statement, ast.If) and len(orelse) == 1 and isinstance(orelse[0], ast.If)
        deepest = walk(orelse, level if elif_chain else level + 1)
        for field_name in ("body", "finalbody", "handlers", "cases"):
            deepest = max(deepest, walk(getattr(statement, field_name, []) or [], level + 1))
        return deepest

    return walk(node.body, 0)


def _node_lines(node: ast.AST) -> int:
    """Lines from the ``def``/``class`` line to the last line, decorators excluded."""
    return (node.end_lineno or node.lineno) - node.lineno + 1


def _import_kind(in_function: bool, in_type_checking: bool) -> str:
    if in_function:
        return "in_function"
    return "type_checking" if in_type_checking else "top_level"


def _is_type_checking(test: ast.expr) -> bool:
    return "TYPE_CHECKING" in ast.unparse(test)


def _resolve(node: ast.ImportFrom, package: str) -> str:
    """The dotted name a ``from ... import`` reaches, with a relative import made absolute.

    One dot means the package the module lives in, so the walk up starts from that package
    and not from the module itself.
    """
    if not node.level:
        return node.module or ""
    parts = package.split(".")
    base = parts[: len(parts) - node.level + 1]
    return ".".join([*base, node.module] if node.module else base)


class _ModuleVisitor:
    """Collects the metrics of one module in a single walk."""

    def __init__(self, module: str, package: str) -> None:
        self.module = module
        self.package = package
        self.functions: list[FunctionMetrics] = []
        self.classes: list[ClassMetrics] = []
        self.imports: list[ImportMetrics] = []

    def visit(self, body: list[ast.stmt], prefix: str, in_function: bool, in_type_checking: bool) -> None:
        for statement in body:
            self._visit_statement(statement, prefix, in_function, in_type_checking)

    def _visit_statement(self, statement: ast.stmt, prefix: str, in_function: bool, in_type_checking: bool) -> None:
        if isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef)):
            self._visit_function(statement, prefix, in_type_checking)
        elif isinstance(statement, ast.ClassDef):
            self._visit_class(statement, prefix, in_function, in_type_checking)
        elif isinstance(statement, (ast.Import, ast.ImportFrom)):
            self._visit_import(statement, _import_kind(in_function, in_type_checking))
        elif isinstance(statement, ast.If):
            type_checking = in_type_checking or _is_type_checking(statement.test)
            self.visit(statement.body, prefix, in_function, type_checking)
            self.visit(statement.orelse, prefix, in_function, in_type_checking)
        else:
            for name in ("body", "orelse", "finalbody", "handlers", "cases"):
                self.visit(getattr(statement, name, []) or [], prefix, in_function, in_type_checking)

    def _visit_import(self, statement: ast.Import | ast.ImportFrom, kind: str) -> None:
        """One arrow per statement: ``import a, b`` names two modules, ``from x import a, b`` one."""
        targets = (
            [alias.name for alias in statement.names]
            if isinstance(statement, ast.Import)
            else [_resolve(statement, self.package)]
        )
        for target in targets:
            self.imports.append(ImportMetrics(self.module, target, kind, statement.lineno))

    def _visit_function(
        self, node: ast.FunctionDef | ast.AsyncFunctionDef, prefix: str, in_type_checking: bool
    ) -> None:
        qualname = f"{prefix}{node.name}"
        self.functions.append(
            FunctionMetrics(
                module=self.module,
                qualname=qualname,
                line=node.lineno,
                lines=_node_lines(node),
                complexity=complexity_of(node),
                parameters=_parameter_count(node, is_method=prefix.endswith(".")),
                depth=depth_of(node),
            )
        )
        self.visit(node.body, f"{qualname}.", in_function=True, in_type_checking=in_type_checking)

    def _visit_class(self, node: ast.ClassDef, prefix: str, in_function: bool, in_type_checking: bool) -> None:
        qualname = f"{prefix}{node.name}"
        methods = sum(isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) for child in node.body)
        self.classes.append(
            ClassMetrics(
                module=self.module,
                name=qualname,
                line=node.lineno,
                lines=_node_lines(node),
                methods=methods,
            )
        )
        self.visit(node.body, f"{qualname}.", in_function, in_type_checking)


def measure_module(source: str, module: str, path: str) -> tuple[ModuleMetrics, _ModuleVisitor]:
    """Metrics of one module, parsed once."""
    tree = ast.parse(source)
    package = module if path.endswith("__init__.py") else module.rpartition(".")[0]
    visitor = _ModuleVisitor(module, package)
    visitor.visit(tree.body, prefix="", in_function=False, in_type_checking=False)
    metrics = ModuleMetrics(
        module=module,
        path=path,
        lines=len(source.splitlines()),
        classes=len(visitor.classes),
        functions=len(visitor.functions),
    )
    return metrics, visitor


def measure(root: Path) -> Report:
    """Measure every module under ``root``."""
    report = Report(modules=[], functions=[], classes=[], imports=[])
    for path in source_files(root):
        module = module_name(path, root)
        metrics, visitor = measure_module(path.read_text(encoding="utf-8"), module, str(path))
        report.modules.append(metrics)
        report.functions.extend(visitor.functions)
        report.classes.extend(visitor.classes)
        report.imports.extend(visitor.imports)
    return report


def package_arrows(
    imports: list[ImportMetrics], modules: list[ModuleMetrics], root_package: str
) -> dict[tuple[str, str, str], int]:
    """Count the arrows between layer packages, per kind.

    Only an import of a module we measured is an arrow: everything else is a dependency on
    the standard library or a package from outside. Arrows inside one layer package are not
    counted, because the layers of chapter 5 say nothing about them.
    """
    known = {metrics.module for metrics in modules}
    arrows: dict[tuple[str, str, str], int] = {}
    for entry in imports:
        if entry.target not in known:
            continue
        source_package = package_of(entry.module, root_package)
        target_package = package_of(entry.target, root_package)
        if source_package == target_package:
            continue
        key = (source_package, target_package, entry.kind)
        arrows[key] = arrows.get(key, 0) + 1
    return arrows


def _above(values: list[int], threshold: int) -> int:
    return sum(1 for value in values if value > threshold)


def _totals(report: Report) -> list[str]:
    by_kind = {kind: sum(1 for entry in report.imports if entry.kind == kind) for kind in IMPORT_KINDS}
    return [
        f"{len(report.modules)} modules, {sum(m.lines for m in report.modules)} regels",
        f"{len(report.functions)} functies en methodes, {len(report.classes)} classes",
        "imports: "
        + ", ".join(f"{by_kind[kind]} {kind}" for kind in IMPORT_KINDS)
        + f" (totaal {len(report.imports)})",
    ]


def _above_thresholds(report: Report) -> list[str]:
    """How much of the code is over each threshold from chapters 3 and 4."""
    function_lines = [f.lines for f in report.functions]
    rows: list[tuple[str, int]] = [
        (f"functies > {FUNCTION_LINES_GUIDE} regels (richtwaarde)", _above(function_lines, FUNCTION_LINES_GUIDE)),
        (f"functies > {FUNCTION_LINES_SIGNAL} regels (signaal)", _above(function_lines, FUNCTION_LINES_SIGNAL)),
        (f"functies > {FUNCTION_LINES_SPLIT} regels (splitsen)", _above(function_lines, FUNCTION_LINES_SPLIT)),
        (f"functies > {COMPLEXITY_MAX} complexiteit", _above([f.complexity for f in report.functions], COMPLEXITY_MAX)),
        (f"functies > {PARAMETERS_MAX} parameters", _above([f.parameters for f in report.functions], PARAMETERS_MAX)),
        (f"functies > {DEPTH_MAX} niveaus diep", _above([f.depth for f in report.functions], DEPTH_MAX)),
    ]
    module_lines = [m.lines for m in report.modules]
    rows += [
        (f"modules > {MODULE_LINES_GUIDE} regels (richtwaarde)", _above(module_lines, MODULE_LINES_GUIDE)),
        (f"modules > {MODULE_LINES_SIGNAL} regels (signaal)", _above(module_lines, MODULE_LINES_SIGNAL)),
        (f"modules > {MODULE_LINES_SPLIT} regels (splitsen)", _above(module_lines, MODULE_LINES_SPLIT)),
    ]
    class_lines = [c.lines for c in report.classes]
    rows += [
        (f"classes > {CLASS_LINES_GUIDE} regels (richtwaarde)", _above(class_lines, CLASS_LINES_GUIDE)),
        (f"classes > {CLASS_LINES_SPLIT} regels (splitsen)", _above(class_lines, CLASS_LINES_SPLIT)),
    ]
    width = max(len(label) for label, _ in rows)
    return ["", "Boven de drempels van hoofdstuk 3 en 4:", *(f"  {label:<{width}} {count}" for label, count in rows)]


def _top_list(title: str, entries: list[str]) -> list[str]:
    return ["", title, *entries]


def _arrows(report: Report, root_package: str) -> list[str]:
    arrows = package_arrows(report.imports, report.modules, root_package)
    totals = [
        f"  {kind}: {sum(count for (_, _, entry_kind), count in arrows.items() if entry_kind == kind)}"
        for kind in IMPORT_KINDS
    ]
    pairs = {(source, target) for source, target, _ in arrows}
    return ["", f"Import-pijlen tussen de packages: {len(pairs)} paren, {sum(arrows.values())} imports", *totals]


def summary(report: Report, root_package: str, top: int) -> str:
    """The short report on stdout: totals, what is above the thresholds, and the worst cases."""
    longest = sorted(report.functions, key=lambda f: f.lines, reverse=True)[:top]
    complex_ = sorted(report.functions, key=lambda f: f.complexity, reverse=True)[:top]
    modules = sorted(report.modules, key=lambda m: m.lines, reverse=True)[:top]
    lines = [
        *_totals(report),
        *_above_thresholds(report),
        *_top_list(
            f"Langste {top} functies:",
            [f"  {e.lines:5} {e.module}:{e.line} {e.qualname}" for e in longest],
        ),
        *_top_list(
            f"Meest complexe {top} functies:",
            [f"  {e.complexity:5} {e.module}:{e.line} {e.qualname}" for e in complex_],
        ),
        *_top_list(f"Langste {top} modules:", [f"  {e.lines:5} {e.module}" for e in modules]),
        *_arrows(report, root_package),
    ]
    return "\n".join(lines)


def write_csv(report: Report, directory: Path, root_package: str) -> list[Path]:
    """Write one CSV per table, so a round can diff its numbers against an earlier run."""
    directory.mkdir(parents=True, exist_ok=True)
    written = []
    tables: list[tuple[str, list[str], list[list]]] = [
        (
            "modules.csv",
            ["module", "path", "lines", "classes", "functions"],
            [[m.module, m.path, m.lines, m.classes, m.functions] for m in report.modules],
        ),
        (
            "functions.csv",
            ["module", "qualname", "line", "lines", "complexity", "parameters", "depth"],
            [[f.module, f.qualname, f.line, f.lines, f.complexity, f.parameters, f.depth] for f in report.functions],
        ),
        (
            "classes.csv",
            ["module", "name", "line", "lines", "methods"],
            [[c.module, c.name, c.line, c.lines, c.methods] for c in report.classes],
        ),
        (
            "imports.csv",
            ["source_package", "target_package", "kind", "count"],
            [
                [source, target, kind, count]
                for (source, target, kind), count in sorted(
                    package_arrows(report.imports, report.modules, root_package).items()
                )
            ],
        ),
    ]
    for name, header, rows in tables:
        path = directory / name
        with path.open("w", newline="", encoding="utf-8") as handle:
            writer = csv.writer(handle)
            writer.writerow(header)
            writer.writerows(rows)
        written.append(path)
    return written


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--root",
        type=Path,
        default=Path(__file__).resolve().parents[1] / "opi",
        help="de package om te meten (standaard: opi/)",
    )
    parser.add_argument("--csv", type=Path, help="schrijf de tabellen als CSV naar deze map")
    parser.add_argument("--top", type=int, default=20, help="lengte van de lijsten in de samenvatting")
    args = parser.parse_args(argv)

    if not args.root.is_dir():
        print(f"{args.root} is geen map", file=sys.stderr)
        return 1

    report = measure(args.root)
    print(summary(report, args.root.name, args.top))
    if args.csv:
        for path in write_csv(report, args.csv, args.root.name):
            print(f"geschreven: {path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
